import heapq

def dijkstra(costs, src):
    dist = {node: float('inf') for node in costs}
    dist[src] = 0
    pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if d != dist[u]:
            continue
        for v, w in costs[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist

costs = {
    1: [(2,10), (3,5)],
    2: [(1,10), (4,2)],
    3: [(1,5), (4,9)],
    4: [(2,2), (3,9)]
}
res = dijkstra(costs, 1)
print(res[2])
print(res[3])
print(res[4])

