#include <stdio.h>
#include <limits.h>
#define N 4
int main(){
    int cost[N][N] = {{0,10,5,INT_MAX},{10,0,INT_MAX,2},{5,INT_MAX,0,9},{INT_MAX,2,9,0}};
    int dist[N];
    int visited[N] = {0};
    for(int i=0;i<N;i++) dist[i]=INT_MAX;
    dist[0]=0; // router 1 index 0
    for(int iter=0; iter<N; iter++){
        int u=-1, min=INT_MAX;
        for(int i=0;i<N;i++) if(!visited[i] && dist[i]<min){min=dist[i]; u=i;}
        if(u==-1) break;
        visited[u]=1;
        for(int v=0; v<N; v++) if(cost[u][v]!=INT_MAX && !visited[v]){
            if(dist[u]+cost[u][v] < dist[v]) dist[v]=dist[u]+cost[u][v];
        }
    }
    printf("%d\n%d\n%d\n", dist[1], dist[2], dist[3]);
    return 0;
}
